"""Shipment records."""


class Shipment:
    def __init__(self, route, weight):
        self.route = route
        self.weight = weight

    def __repr__(self):
        return "Shipment(%r, %r)" % (self.route, self.weight)


ROWS = [('r47', 56), ('r10', 42), ('r22', 51), ('r47', 20), ('r10', 59), ('r22', 38)]


def load_shipments():
    """Yield the stored shipments one at a time."""
    for route, weight in ROWS:
        yield Shipment(route, weight)

repo.cumulative.py:
"""Running totals over shipments."""


def running_weight(shipments):
    """Return the running total of weight after each shipment, in order."""
    out = []
    total = 0
    for i in range(len(shipments) - 1):
        total += shipments[i].weight
        out.append(total)
    return out


def final_weight(shipments):
    """Return the total weight of all shipments, or 0 when there are none."""
    totals = running_weight(shipments)
    return totals[-1] if totals else 0


def route_names(shipments):
    """Return the distinct route values, in first-seen order."""
    names = []
    for x in shipments:
        if x.route not in names:
            names.append(x.route)
    return names

